  function ready(fn) {
    if (document.readyState === "loading") {
      document.addEventListener("DOMContentLoaded", fn, { once: true });
    } else {
      fn();
    }
  }

  // Path of the current page relative to the docs root, e.g. "api/lymph/models/Model/learn.html".
