    var root = "";
    if (window.DOCUMENTATION_OPTIONS && typeof window.DOCUMENTATION_OPTIONS.URL_ROOT === "string") {
      root = window.DOCUMENTATION_OPTIONS.URL_ROOT;
    } else {
      var attr = document.documentElement.getAttribute("data-content_root");
      if (attr) root = attr;
    }
